function EmojiRenderer({tnode, style: styleProp}: CustomRendererProps<TText | TPhrasing>) {
    const styles = useThemeStyles();
    const style = {...styleProp, ...('islarge' in tnode.attributes ? styles.onlyEmojisText : {})};
